ist) || (($list instanceof \think\Collection || $list instanceof \think\Paginator ) && $list->isEmpty()))): ?><thead><tr><th class='text-left nowrap' width="40%">投资信息</th><th class='text-left nowrap' width="15%">投资人</th><th class='text-left nowrap' width="15%">投资数据</th><th class="text-left nowrap" width="15%">投资时间</th></tr></thead><?php endif; ?><tbody><?php foreach($list as $key=>$vo): ?><tr><td class='text-left nowrap' style="max-width: 260px;overflow: hidden">                项目名称：<?php echo htmlentities((isset($vo['title']) && ($vo['title'] !== '')?$vo['title']:'--')); ?><br>                返款编号：<?php echo htmlentities((isset($vo['id']) && ($vo['id'] !== '')?$vo['id']:'--')); ?><br></td><td class='text-left nowrap'>                投资人ID：<?php echo htmlentities((isset($vo['uid']) && ($vo['uid'] !== '')?$vo['uid']:'--')); ?><br>                投资人姓名：<?php echo htmlentities((isset($vo['name']) && ($vo['name'] !== '')?$vo['name']:'--')); ?><br>                投资人电话：<?php echo htmlentities((isset($vo['phone']) && ($vo['phone'] !== '')?$vo['phone']:'--')); ?><br></td><td class='text-left nowrap'>                预计返款金额：<?php echo htmlentities((isset($vo['pay1']) && ($vo['pay1'] !== '')?$vo['pay1']:'--')); ?> 元<br>                实际返款金额：<?php echo htmlentities((isset($vo['pay2']) && ($vo['pay2'] !== '')?$vo['pay2']:'--')); ?> 元<br></td><td class='text-left nowrap'>                预计返款：<?php echo htmlentities((isset($vo['time1']) && ($vo['time1'] !== '')?$vo['time1']:'--')); ?><br>                实际返款：<?php echo htmlentities((isset($vo['time2']) && ($vo['time2'] !== '')?$vo['time2']:'--')); ?><br></td></tr><?php endforeach; ?></tbody></table><?php if(empty($list) || (($list instanceof \think\Collection || $list instanceof \think\Paginator ) && $list->isEmpty())): ?><span class="notdata">没有记录哦</span><?php else: ?><?php echo (isset($pagehtml) && ($pagehtml !== '')?$pagehtml:''); ?><?php endif; ?></div></div></div>